CREATE TABLE public.portfolio_content (
  id text PRIMARY KEY,
  content jsonb NOT NULL,
  images jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.portfolio_content TO anon, authenticated;
GRANT ALL ON public.portfolio_content TO service_role;
ALTER TABLE public.portfolio_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Portfolio is publicly readable" ON public.portfolio_content FOR SELECT TO anon, authenticated USING (id = 'main');
CREATE OR REPLACE FUNCTION public.set_portfolio_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TRIGGER portfolio_content_updated_at BEFORE UPDATE ON public.portfolio_content FOR EACH ROW EXECUTE FUNCTION public.set_portfolio_updated_at();
INSERT INTO public.portfolio_content (id, content, images) VALUES (
'main',
'{"name":"Emad Tamer Mashali","headline":"Computer & Communication Engineering Student | UI/UX Designer | Aspiring Web Developer","intro":["I am a Computer & Communication Engineering student interested in software development, UI/UX, AI, cybersecurity, and emerging technologies.","I enjoy working on both technical and creative projects, especially projects where I can combine problem-solving with design. I am currently developing my web-development skills while continuing to build experience through university projects, training, and extracurricular activities."],"about":["I am currently studying Computer & Communication Engineering at Mansoura National University.","My interests are mainly focused on technology and how it can be used to create useful and user-friendly solutions. I have experience in UI/UX design through training and personal projects, while I am also developing my skills in programming and web development.","I also enjoy working with teams, organizing activities, communicating with people, and taking responsibility for projects and events."],"projects":[{"title":"Carco — Car Wash Booking App","category":"UI/UX Design","tools":"Figma","description":"A user-centered mobile application concept designed to make booking car-wash services easier and more organized.","work":["Conducted user research","Defined the application structure","Created user flows","Designed wireframes","Designed the user interface","Created a clickable Figma prototype","Worked on notification settings","Designed features such as Wheel Polish","Applied a consistent design system","Conducted usability testing"],"outcome":"A complete interactive prototype demonstrating the main user journey from selecting a service to booking a car wash.","linkLabel":"Figma prototype","link":""},{"title":"Line-Follower Robot","category":"Arduino / Embedded Systems","tools":"Arduino, sensors, motor control","description":"An Arduino-based robot designed to follow a predefined line automatically.","work":["Worked with Arduino","Worked with sensors and motor control","Helped implement the robot movement logic","Tested and adjusted the system to improve track following"],"outcome":"Skills demonstrated: Arduino, basic embedded systems, sensors, electronics, and problem-solving.","linkLabel":"Project photos / code","link":""},{"title":"Obstacle-Avoiding Robot","category":"Arduino / Embedded Systems","tools":"Arduino, sensors, motor control","description":"An autonomous Arduino-based robot designed to detect obstacles and change its movement accordingly.","work":["Worked with sensors","Implemented obstacle detection","Worked with motor control","Tested the robot in different situations","Adjusted the system based on its behavior"],"outcome":"Skills demonstrated: Arduino, sensors, electronics, embedded programming, and troubleshooting.","linkLabel":"Project photos / code","link":""}],"experience":[{"title":"IEEE MNU Student Branch","subtitle":"HR — Media Department","body":"I am currently a member of the IEEE MNU Student Branch, working as HR in the Media Department. Through this experience, I have gained a better understanding of teamwork, communication, and how student-branch activities are organized. I am also interested in contributing more through technology and digital platforms."},{"title":"NTI UI/UX Summer Training Program","subtitle":"ITIDA / NTI · 120 Hours · Final Score: 96%","body":"Completed a 120-hour UI/UX training program covering user research, user flows, information architecture, wireframing, UI design, prototyping, design systems, usability testing, Figma, freelancing fundamentals, client communication, project presentation, requirements, services, and deliverables. The final project was the Carco car-wash booking application."},{"title":"Event & Leadership Experience","subtitle":"Academic activities and events","body":"Contributed to AI Engineering Graduation Projects Defense, English II Project Showcase, and the Engineering & International Forum. These experiences strengthened my communication, organization, teamwork, and ability to handle unexpected situations."}],"skills":{"UI/UX Design":["Figma","User Research","User Flows","Wireframing","Prototyping","UI Design","Design Systems","Usability Testing"],"Web Development":["HTML","CSS","JavaScript","Responsive Web Design","VS Code","GitHub"],"Programming":["C#","Basic Programming Concepts","Arduino / Embedded Programming"],"Engineering":["Electronics","Arduino","Sensors","Physical Prototyping","Engineering Problem-Solving"],"Other":["Teamwork","Communication","Event Organization","Leadership","Presentation"]},"certifications":["NTI / ITIDA UI/UX Summer Training — 120 Hours — 96%","Cisco Networking Academy — Introduction to Cybersecurity","Cisco Networking Academy — Digital Safety","Cisco Networking Academy — Networking Basics","Cisco Networking Academy — Industrial Networking Essentials","Cisco Networking Academy — Network Technician Exam","Cisco Networking Academy — Modern AI","Cisco Networking Academy — IoT & Digital Transformation","Huawei ICT Academy — Overview of AI","Huawei ICT Academy — Overview of IoT Technologies","Microsoft Learn — Web Development / VS Code","GitHub Learning"],"learning":["HTML & CSS","JavaScript","Git & GitHub","C#","Software development","AI engineering","UI/UX"],"learningNote":"I am especially interested in building projects rather than only learning theory, so I try to apply what I learn to practical projects whenever possible.","email":"hight.ball.space@gmail.com","linkedin":"https://www.linkedin.com/in/emad-mashali"}'::jsonb,
